-- Multi-user and encryption: users (with the key pair, the recovery verifier, two-step verification and language columns), addresses,
-- domains, audit_log, user_sign_ins, user_security_events, user_keys, recovery_codes, recovery_tickets, two_factor_challenges, an owner column
-- on messages and push_subscriptions, the EM1 columns of messages and attachments, and `messages.origin` ('smtp' for every old row). Organisation settings (require_2fa, default_language)
-- live in the existing `settings` table.
-- Generated by `drizzle-kit generate`, then hand-edited in one place: the two ALTER TABLE ... ADD `user_id` statements carry
-- ON DELETE cascade (drizzle-kit leaves it out of ALTER TABLE), so the database matches schema.ts.
-- No data is touched here: existing rows keep user_id NULL until the first-run setup (POST /api/auth/setup) assigns them to the admin,
-- and keep enc_fmt 0 (plaintext) until the encryption job (cron) has converted them.
CREATE TABLE `addresses` (
	`address` text PRIMARY KEY NOT NULL,
	`user_id` text NOT NULL,
	`kind` text NOT NULL,
	FOREIGN KEY (`user_id`) REFERENCES `users`(`id`) ON UPDATE no action ON DELETE cascade,
	CONSTRAINT "addresses_kind_check" CHECK("addresses"."kind" IN ('primary', 'alias'))
);
--> statement-breakpoint
CREATE INDEX `idx_addresses_user_id` ON `addresses` (`user_id`);--> statement-breakpoint
CREATE UNIQUE INDEX `idx_addresses_one_primary` ON `addresses` (`user_id`) WHERE "addresses"."kind" = 'primary';--> statement-breakpoint
